const cfg = $input.first().json || {};
const wb = cfg.workflowBackup || {};
const pad = (n) => String(n).padStart(2, '0');
const now = new Date();
const backup_timestamp =
  now.getFullYear() +
  '-' +
  pad(now.getMonth() + 1) +
  '-' +
  pad(now.getDate()) +
  '_' +
  pad(now.getHours()) +
  '-' +
  pad(now.getMinutes()) +
  '-' +
  pad(now.getSeconds());
const m = wb.minutesPerWorkflowManual;
const minutes_per_workflow_manual = typeof m === 'number' && !Number.isNaN(m) ? m : 5;
const backup_folder_name = 'wfBackup - ' + backup_timestamp;

return [{
  json: {
    gdrive_folder_id: wb.gdriveParentFolderId || '1Re6nTdYldLFZdWk346KqN-cFCJkynEG1',
    gdrive_shared_drive_id: wb.gdriveSharedDriveId || '0AFmBrzlxIst5Uk9PVA',
    gdrive_shared_drive_cached_name: wb.gdriveSharedDriveName || 'Internal-Ops',
    backup_timestamp,
    backup_folder_name,
    minutes_per_workflow_manual,
    execution_start_time: now.toISOString(),
    execution_start_timestamp: now.getTime()
  }
}];

// n8n API: active=true => published only (activeVersionId set). Still include archived rows; drop those here.
const rows = $input.all();
return rows
  .filter(({ json }) => json.isArchived !== true)
  .map((item) => ({ json: item.json, pairedItem: item.pairedItem }));

const workflow = $json;

if (!workflow.name && workflow.total_workflows) {
  throw new Error('Receiving baseline tracking data instead of workflow object. Check wiring from Loop Over Workflows.');
}

const date = new Date();
const year = date.getFullYear();
const month = String(date.getMonth() + 1).padStart(2, '0');
const wfId = workflow.id != null ? String(workflow.id) : 'unknown';
const rawName = String(workflow.name || 'unnamed');

const sysMatch = rawName.match(/^SYS\s*(\d+)(?:\.(\d+))?\s*[—\-]?\s*/i);
let prefix;
if (sysMatch) {
  const major = String(parseInt(sysMatch[1], 10)).padStart(2, '0');
  if (sysMatch[2] != null && sysMatch[2] !== '') {
    const minor = String(parseInt(sysMatch[2], 10));
    prefix = 'SYS_' + major + '_' + minor;
  } else {
    prefix = 'SYS_' + major;
  }
} else {
  prefix = 'WORKFLOW';
}

let title = rawName;
if (sysMatch) {
  title = rawName.slice(sysMatch[0].length).trim();
}
const nameSlug = title
  .replace(/[^a-zA-Z0-9\s-_]/g, '')
  .replace(/\s+/g, '_')
  .replace(/_+/g, '_')
  .replace(/^_|_$/g, '')
  .slice(0, 80);
const safeSlug = nameSlug || 'unnamed';

const backup_file_base = prefix + '_' + safeSlug + '_' + wfId;

const drive_relative_path = year + '/' + month + '/' + backup_file_base + '.json';

const orderJsonKeys = (jsonObj) => {
  const ordered = {};
  Object.keys(jsonObj).sort().forEach((key) => {
    ordered[key] = jsonObj[key];
  });
  return ordered;
};

const orderedWorkflow = orderJsonKeys(workflow);
const workflowJson = JSON.stringify(orderedWorkflow, null, 2);

return {
  ...workflow,
  drive_relative_path,
  workflow_json: workflowJson,
  year,
  month,
  sanitized_name: safeSlug,
  backup_file_base,
};

const input = $input.first().json || {};
const config = $('Config').first().json;
const workflows = $('Published workflows only').all();
const totalWorkflows = workflows.length;
const minutesPerWorkflow = config.minutes_per_workflow_manual || 5;
const totalManualMinutes = totalWorkflows * minutesPerWorkflow;

return {
  ...input,
  total_workflows: totalWorkflows,
  minutes_per_workflow_manual: minutesPerWorkflow,
  total_manual_minutes_estimate: totalManualMinutes,
  execution_start_time: config.execution_start_time,
  execution_start_timestamp: config.execution_start_timestamp,
  tracking_initialized: true
};

// Get execution data
const config = $('Config').first().json;
const trackingBaseline = $('Calculate Time Tracking Baseline').first().json;
const executionEndTimestamp = Date.now();

// Calculate actual execution duration
const executionStartTimestamp = trackingBaseline.execution_start_timestamp;
const executionDurationMs = executionEndTimestamp - executionStartTimestamp;
const executionDurationMinutes = Math.round(executionDurationMs / 60000 * 100) / 100;

// Calculate time saved
const manualTimeMinutes = trackingBaseline.total_manual_minutes_estimate;
const actualTimeSaved = manualTimeMinutes - executionDurationMinutes;
const efficiencyPercent = Math.round((actualTimeSaved / manualTimeMinutes) * 100);

// Prepare comprehensive time tracking data
return {
  // Baseline data
  total_workflows_backed_up: trackingBaseline.total_workflows,
  minutes_per_workflow_manual: trackingBaseline.minutes_per_workflow_manual,

  // Execution metrics
  execution_start_time: trackingBaseline.execution_start_time,
  execution_end_time: new Date(executionEndTimestamp).toISOString(),
  execution_duration_minutes: executionDurationMinutes,
  execution_duration_seconds: Math.round(executionDurationMs / 1000),

  // Time savings calculation
  estimated_manual_time_minutes: manualTimeMinutes,
  actual_time_saved_minutes: actualTimeSaved,
  efficiency_percent: efficiencyPercent,

  // Human-readable summary
  time_saved_display: `${Math.floor(actualTimeSaved)} minutes ${Math.round((actualTimeSaved % 1) * 60)} seconds`,
  efficiency_display: `${efficiencyPercent}% faster than manual`,

  // For n8n Time Saved widget compatibility
  minutesSaved: Math.round(actualTimeSaved)
};

const d = $input.first().json || {};
const nl = String.fromCharCode(10);
const lines = [
  '*n8n workflow backup complete*',
  `Status: ${d.status ?? ''}`,
  `Total workflows: ${d.total_workflows ?? ''}`,
  `Timestamp: ${d.backup_timestamp ?? ''}`,
  `Drive folder: ${d.gdrive_folder ?? ''}`,
  `Execution: ${d.execution_duration ?? ''}`,
  `Time saved: ${d.time_saved ?? ''}`,
  `Efficiency: ${d.efficiency ?? ''}`,
  `Minutes saved (est.): ${d.minutes_saved ?? ''}`
];
return [{ json: { message: lines.join(nl), priority: 'info' } }];

